"""Generate the APB decoder metadata from the canonical register schema."""

import argparse
import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
SCHEMA = ROOT / "config/contracts/registers.json"
OUTPUT = Path(__file__).with_name("lpddr5_mc_apb_metadata_pkg.sv")


def render() -> str:
    regs = json.loads(SCHEMA.read_text())["registers"]
    lines = [
        "// Generated by rtl/control/generate_apb_metadata.py; do not edit.",
        "// Canonical schema SHA-256: " + hashlib.sha256(SCHEMA.read_bytes()).hexdigest(),
        "package lpddr5_mc_apb_metadata_pkg;",
        "  /* verilator lint_off UNUSEDPARAM */",
        f"  localparam int REG_COUNT = {len(regs)};",
    ]
    for index, reg in enumerate(regs):
        lines.append(f"  localparam int INDEX_{reg['name']} = {index};")
    attrs = {
        "OFFSET": ("logic [15:0]", [f"16'h{r['offset']:04x}" for r in regs]),
        "SHARED": ("logic", [str(int(r["scope"] == "shared")) for r in regs]),
        "RESET": ("logic [31:0]", [f"32'h{r['reset']:08x}" for r in regs]),
        "LOCK": (
            "logic [1:0]",
            [str({"none": 0, "disabled": 1, "quiesced": 2, "inactive_or_quiesced": 3}[r["lock"]]) for r in regs],
        ),
        "FSP": (
            "int",
            [r["name"][3] if r["name"].startswith("FSP") and r["name"][3].isdigit() else "-1" for r in regs],
        ),
    }
    for access in ("rw", "ro", "w1s", "w1c"):
        attrs[access.upper()] = (
            "logic [31:0]",
            [
                f"32'h{sum(((1 << f['width']) - 1) << f['lsb'] for f in r['fields'] if f['access'] == access):08x}"
                for r in regs
            ],
        )
    for name, (kind, values) in attrs.items():
        lines.append(f"  localparam {kind} REG_{name} [REG_COUNT] = '{{")
        lines += [
            "    " + ", ".join(values[i : i + 8]) + ("," if i + 8 < len(values) else "")
            for i in range(0, len(values), 8)
        ]
        lines.append("  };")
    for field in ("BASE_LO", "BASE_HI", "SIZE_4K", "ATTR", "MAP"):
        lines.append(
            f"  localparam int REGION_{field}_INDEX [8] = '{{"
            + ", ".join(f"INDEX_REGION_{i}_{field}" for i in range(8))
            + "};"
        )
    lines.append("  localparam int REGION_BIT_INDEX [8][40] = '{")
    for region in range(8):
        lines.append(
            "    '{"
            + ", ".join(f"INDEX_REGION_{region}_BIT_{bit}" for bit in range(40))
            + "}"
            + ("," if region != 7 else "")
        )
    lines += [
        "  };",
        "  typedef logic [REG_COUNT-1:0][31:0] lpddr5_mc_register_image_t;",
        "  /* verilator lint_on UNUSEDPARAM */",
        "endpackage",
        "",
    ]
    return "\n".join(lines)


def main() -> None:
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    content = render()
    if args.check:
        if not OUTPUT.exists() or OUTPUT.read_text() != content:
            raise SystemExit("APB metadata is stale")
    else:
        OUTPUT.write_text(content)


if __name__ == "__main__":
    main()
